import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷五·21","description":"易小帖 - 卷五·21","frontmatter":{"title":"卷五·21","description":"易小帖 - 卷五·21"},"headers":[],"relativePath":"zh/classics/yixiaotie/143.md","filePath":"zh/classics/yixiaotie/143.md"}'),o={name:"zh/classics/yixiaotie/143.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷五·21",tabindex:"-1"},[r("卷五·21 "),e("a",{class:"header-anchor",href:"#卷五·21","aria-label":"Permalink to “卷五·21”"},"​")],-1),e("p",null,"答：人不能解，易苟以為能幹父蠱，即不問父與考，死與生，爻義詞義一概蒙溷，但曰有子而已。殊不知，父與考不同。父者生，父考者死。父也既名考，則爾時父死可知也。然仍稱父，則蠱尚未乾父，此時又不可以死也。故必也有子乾之，而後可曰此考矣。今而後，其可死矣。是乾蠱之子，願考父不願父父也，父父則死而復生矣。此其義。推易有之。蠱從泰來，以泰初三乾之陽，推而為蠱初下巽之陰，乾為父，是亡父也。又蠱從損來，以損初互坤之兌，推而為互震倒兌之陰，坤為死，今無坤則不死也。然而震為生，將欲生而又為倒兌以毀折之，是生仍不生也。蓋卦義爻位，原有死而復生之象，而乾之有子，則概反之。是妖非兆，是考非父，是乾非不乾，演辭占筮，兩俱妙合，向非推易，其能發京易之秘有如是乎。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
